--- a/src/schedule.cpp
+++ b/src/schedule.cpp
@@ -10,16 +10,29 @@ namespace clinic {

 constexpr int kLongVisitMinutes = 60;

-void SplitLongVisits(std::vector<Visit>& visits) {
-    (void)visits;
+void SplitLongVisits(std::vector<Visit>& visits) {
+    for (auto& visit : visits) {
+        if (visit.minutes <= kLongVisitMinutes) {
+            continue;
+        }
+
+        const int half = visit.minutes / 2;
+        visit.minutes = half;
+
+        Visit tail = visit;
+        tail.at = visit.at + std::chrono::minutes(half);
+
+        visits.push_back(tail);
+    }
 }

 int TotalMinutes(const std::vector<Visit>& visits) {
     int total = 0;
     for (const auto& visit : visits) {
         total += visit.minutes;
     }
     return total;
 }

 }  // namespace clinic
